<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Webhooki · '.$space['name'];?>
<div class="page-head"><div><p class="eyebrow"><?=Html::e($space['name'])?></p><h1>Webhooki</h1></div><a class="button secondary" href="<?=Html::e(Url::to('/spaces/'.$space['space_key']))?>">Wróć</a></div>
<?php if($createdSecret):?><div class="alert success"><strong>Sekret webhooka — skopiuj teraz.</strong><code class="secret-once"><?=Html::e($createdSecret)?></code><p>Nie będzie ponownie wyświetlony.</p></div><?php endif;?>
<?php if(isset($_GET['error'])):?><div class="alert danger">Nie udało się utworzyć webhooka. Endpoint musi być publicznym adresem HTTP/HTTPS, a zdarzenia muszą być dozwolone.</div><?php endif;?>
<section class="card section-card"><h2>Dodaj webhook</h2><form method="post" class="grid compact-form"><?=Csrf::field()?><label>Nazwa<input name="name" maxlength="150" required></label><label>Endpoint URL<input name="url" type="url" maxlength="1000" required placeholder="https://hooks.example.org/imwiki"></label><fieldset><legend>Zdarzenia</legend><?php foreach($events as $event):?><label class="check-row"><input type="checkbox" name="events[]" value="<?=Html::e($event)?>"> <?=Html::e($event)?></label><?php endforeach;?></fieldset><div class="form-action"><button class="button">Utwórz webhook</button></div></form></section>
<section class="card section-card"><h2>Skonfigurowane</h2><?php if(!$webhooks):?><div class="empty-state"><p class="muted">Brak webhooków.</p></div><?php endif;?><?php foreach($webhooks as $hook):?><div class="list-row"><div><strong><?=Html::e($hook['name'])?></strong><small><?=Html::e($hook['endpoint_url'])?><br><?=Html::e(implode(', ',$hook['events']))?> · <?=$hook['enabled']?'aktywny':'wyłączony'?></small></div><?php if($hook['enabled']):?><form method="post" action="<?=Html::e(Url::to('/spaces/'.$space['space_key'].'/webhooks/'.$hook['id'].'/revoke'))?>"><?=Csrf::field()?><button class="button secondary">Wyłącz</button></form><?php endif;?></div><?php endforeach;?></section>
